     # not processing as this is not the actual sequence\n            return\n\n    if IS_SPEC_DECODING:\n        # The rolling of conv state:\n        #\n        # Before forward, the conv_state is:\n        # [history1, history2, ..., historyM].\n        #\n        # After forward, the conv_state becomes:\n        # [history2, ..., historyM, draft1, draft2, ..., draftN].\n        #\n        # After acceptance, it becomes:\n        #\n        # - accept 1 tokens: [history2, ..., historyM, draft1]\n        # - accept 2 tokens: [history3, ..., historyM, draft1, draft2]\n        # - and so on.\n        conv_state_token_offset = (tl.load(num_accepted_tokens_ptr + idx_seq) -\n                                   1)\n    else:\n        conv_state_token_offset = 0\n\n    # STEP 1: READ init_state data\n    conv_states_base = (conv_state_ptr +\n                        (conv_state_batch_coord * stride_conv_state_seq) +\n                        (idx_feats * stride_conv_state_dim))\n    mask_w = idx_feats < dim\n\n    prior_tokens = conv_states_base + conv_state_token_offset * stride_conv_state_tok\n    if KERNEL_WIDTH >= 2:\n        conv_states_ptrs = prior_tokens  # [BLOCK_N]\n        col0 = tl.load(conv_states_ptrs, mask_w, 0.0)\n    if KERNEL_WIDTH >= 3:\n        conv_states_ptrs = prior_tokens + 1 * stride_conv_state_tok  # [BLOCK_N]\n        col1 = tl.load(conv_states_ptrs, mask_w, 0.0)\n    if KERNEL_WIDTH >= 4:\n        conv_states_ptrs = prior_tokens + 2 * stride_conv_state_tok  # [BLOCK_N]\n        col2 = tl.load(conv_states_ptrs, mask_w, 0.0)\n    if KERNEL_WIDTH == 5:\n        conv_states_ptrs = prior_tokens + 3 * stride_conv_state_tok  # [BLOCK_N]\n        col3 = tl.load(conv_states_ptrs, mask_w, 0.0)\n\n    # STEP 2: assume state_len > seqlen\n    idx_tokens = tl.arange(0, NP2_STATELEN)  # [BLOCK_M]\n\n    # The conv_state updates works in a sliding window manner,\n    # at each forward pass, the tokens are shift by 1, so we\n    # load since idx_tokens + 1.\n    if IS_SPEC_DECODING:\n        conv_state_source_offset = conv_state_token_offset + 1\n    else:\n        conv_state_source_offset = seqlen\n    conv_state_ptrs_source = (\n        conv_state_ptr + (conv_state_batch_coord * stride_conv_state_seq) +\n        conv_state_source_offset * stride_conv_state_tok +\n        (idx_feats * stride_conv_state_dim)[None, :] +\n        (idx_tokens * stride_conv_state_tok)[:, None]\n    )  # [BLOCK_M, BLOCK_N]\n    mask = ((conv_state_batch_coord < num_cache_lines)\n            & ((idx_tokens + seqlen) < state_len)[:, None]\n            & (idx_feats < dim)[None, :])\n    conv_state = tl.load(conv_state_ptrs_source, mask, other=0.0)\n\n    VAL = state_len - seqlen\n    x_base = x_ptr + (idx_seq * stride_x_seq) + (idx_feats * stride_x_dim\n                                                 )  # [BLOCK_N]\n\n    x_ptrs = x_base[None, :] + (\n        (idx_tokens - VAL) * stride_x_token)[:, None]  # [BLOCK_M, BLOCK_N]\n\n    mask_x = ((idx_tokens - VAL >= 0)[:, None] &\n              (idx_tokens - VAL < seqlen)[:, None] & (idx_feats < dim)[None, :]\n              )  # token-index  # token-index  # feature-index\n    loaded_x = tl.load(x_ptrs, mask_x, 0.0)\n    tl.debug_barrier()\n\n    new_conv_state = tl.where(mask, conv_state, loaded_x)\n\n    conv_state_base = (conv_state_ptr +\n                       (conv_state_batch_coord * stride_conv_state_seq) +\n                       (idx_feats * stride_conv_state_dim))  # [BLOCK_N,]\n    conv_state_ptrs_target = conv_state_base + (\n        idx_tokens * stride_conv_state_tok)[:, None]  # [BLOCK_M, BLOCK_N]\n    mask = (idx_tokens < state_len)[:, None] & (idx_feats < dim)[None, :]\n    tl.store(conv_state_ptrs_target, new_conv_state, mask)\n\n    # STEP 3: init accumulator\n    if HAS_BIAS:\n        bias = bias_ptr + idx_feats\n        mask_bias = idx_feats < dim\n        acc_preload = tl.load(bias, mask=mask_bias,\n                              other=0.0).to(tl.float32)  # [BLOCK_N]\n    else:\n        acc_preload = tl.zeros((BLOCK_N, ), dtype=tl.float32)\n\n    # STEP 4:\n    # PRE-LOAD WEIGHTS\n    # first kernel column, configured for weights to handle BLOCK_N features in range\n    w_base = w_ptr + (idx_feats * stride_w_dim)  # [BLOCK_N,]\n    mask_w = idx_feats < dim\n    if KERNEL_WIDTH >= 2:\n        w_ptrs = w_base + (0 * stride_w_width)  # [BLOCK_N] tensor\n        w_col0 = tl.load(w_ptrs, mask_w, other=0.0)\n        w_ptrs = w_base + (1 * stride_w_width)  # [BLOCK_N] tensor\n        w_col1 = tl.load(w_ptrs, mask_w, other=0.0)\n    if KERNEL_WIDTH >= 3:\n        w_ptrs = w_base + (2 * stride_w_width)  # [BLOCK_N] tensor\n        w_col2 = tl.load(w_ptrs, mask_w, other=0.0)\n    if KERNEL_WIDTH >= 4:\n        w_ptrs = w_base + (3 * stride_w_width)  # [BLOCK_N] tensor\n        w_col3 = tl.load(w_ptrs, mask_w, other=0.0)\n\n    x_base_1d = x_base  # starting of chunk [BLOCK_N]\n    mask_x_1d = idx_feats < dim\n\n    # STEP 5: compute each token\n    for idx_token in tl.static_range(seqlen):\n        acc = acc_preload\n\n        matrix_w = w_col0\n        matrix_x = col0\n        for j in tl.static_range(KERNEL_WIDTH):\n            if KERNEL_WIDTH == 2:\n                if j == 1:  # KERNEL_WIDTH-1:\n                    matrix_w = w_col1\n                    x_ptrs_1d = x_base_1d + idx_token * stride_x_token  # [BLOCK_N]\n                    matrix_x = tl.load(x_ptrs_1d, mask=mask_x_1d)\n            elif KERNEL_WIDTH == 3:\n                if j == 1:\n                    matrix_w = w_col1\n                    matrix_x = col1\n                elif j == 2:\n                    matrix_w = w_col2\n                    x_ptrs_1d = x_base_1d + idx_token * stride_x_token  # [BLOCK_N]\n                    matrix_x = tl.load(x_ptrs_1d, mask=mask_x_1d)\n            elif KERNEL_WIDTH == 4:\n                if j == 1:\n                    matrix_w = w_col1\n                    matrix_x = col1\n                elif j == 2:\n                    matrix_w = w_col2\n                    matrix_x = col2\n                elif j == 3:\n                    matrix_w = w_col3\n                    x_ptrs_1d = x_base_1d + idx_token * stride_x_token  # [BLOCK_N]\n                    matrix_x = tl.load(x_ptrs_1d, mask=mask_x_1d)\n\n            acc += matrix_x * matrix_w  # [BLOCK_N]\n\n        if KERNEL_WIDTH == 2:\n            col0 = matrix_x\n        elif KERNEL_WIDTH == 3:\n            col0 = col1\n            col1 = matrix_x\n        elif KERNEL_WIDTH == 4:\n            col0 = col1\n            col1 = col2\n            col2 = matrix_x\n\n        if SILU_ACTIVATION:\n            acc = acc / (1 + tl.exp(-acc))\n        mask_1d = (idx_token < seqlen) & (idx_feats < dim\n                                          )  # token-index  # feature-index\n        o_ptrs = o_ptr + (\n            idx_seq) * stride_o_seq + idx_token * stride_o_token + (\n                idx_feats * stride_o_dim)\n\n        tl.store(o_ptrs, acc, mask=mask_1d)",
        "causal_conv1d_update": "def causal_conv1d_update(\n    x: torch.Tensor,\n    conv_state: torch.Tensor,\n    weight: torch.Tensor,\n    bias: Optional[torch.Tensor] = None,\n    activation: Union[bool, str, None] = None,\n    cache_seqlens: Optional[torch.Tensor] = None,\n    conv_state_indices: Optional[torch.Tensor] = None,\n    num_accepted_tokens: Optional[torch.Tensor] = None,\n    pad_slot_id: int = PAD_SLOT_ID,\n    metadata=None,\n    validate_data=False,\n):\n    \"\"\"\n    x: (batch, dim) or (batch, dim, seqlen)\n        [shape=2: single token prediction]\n        [shape=3: single or multiple tokens prediction]\n    conv_state: (..., dim, state_len), where state_len >= width - 1\n    weight: (dim, width)\n    bias: (dim,)\n    cache_seqlens: (batch,), dtype int32.\n        If not None, the conv_state is treated as a circular buffer.\n        The conv_state will be updated by copying x to the conv_state\n        starting at the index\n        @cache_seqlens % state_len.\n    conv_state_indices: (batch,), dtype int32\n        If not None, the conv_state is a larger tensor along the batch dim,\n        and we are selecting the batch coords specified by conv_state_indices.\n        Useful for a continuous batching scenario.\n    pad_slot_id: int\n            if cache_indices is passed, lets the kernel identify padded\n            entries that will not be processed,\n            for example: cache_indices = [pad_slot_id, 1 ,20 ,pad_slot_id]\n            in this case, the kernel will not process entries at\n            indices 0 and 3\n    out: (batch, dim) or (batch, dim, seqlen)\n    \"\"\"\n    if validate_data:\n        assert cache_seqlens is None  # not implemented yet - ok for vLLM\n        assert pad_slot_id is not None\n        assert x.stride(1) == 1\n    if isinstance(activation, bool):\n        activation = \"silu\" if activation is True else None\n    elif activation is not None:\n        assert activation in [\"silu\", \"swish\"]\n    unsqueeze = x.dim() == 2\n    if unsqueeze:\n        # make it (batch, dim, seqlen) with seqlen == 1\n        x = x.unsqueeze(-1)\n    batch, dim, seqlen = x.shape\n    _, width = weight.shape\n    # conv_state: (..., dim, state_len), where state_len >= width - 1\n    num_cache_lines, _, state_len = conv_state.size()\n\n    if validate_data:\n        assert dim == weight.size(0)\n        assert conv_state.stride(\n            -2\n        ) == 1, f\"ERROR: expect contiguous along feat-dim of conv_state (currently stride={conv_state.stride()})\"\n        assert state_len >= width - 1\n        # when above happens, we don't shift-left to keep any records in conv_state\n        assert dim == conv_state.size(1)\n        if conv_state_indices is None:\n            assert conv_state.size(0) >= batch\n        else:\n            assert (batch, ) == conv_state_indices.shape\n\n        assert num_cache_lines >= batch\n        assert weight.stride(1) == 1  # Need this\n        assert cache_seqlens is None  # not needed for vLLM - circular buffer\n\n    # adopt the strategy in vLLM that overwrite on 'x' directly, rather than creating a new tensor 'o'\n    out = x\n    stride_w_dim, stride_w_width = weight.stride()\n\n    stride_x_seq, stride_x_dim, stride_x_token = x.stride(\n    )  # X (batch, dim, seqlen)\n\n    stride_o_seq, stride_o_dim, stride_o_token = out.stride()\n    stride_istate_seq, stride_istate_dim, stride_istate_token = conv_state.stride(\n    )\n    stride_state_indices = conv_state_indices.stride(\n        0) if conv_state_indices is not None else 0\n    if num_accepted_tokens is not None:\n        state_len = width - 1 + (seqlen - 1)  # effective state_len needed\n    else:\n        state_len = width - 1\n    np2_statelen = triton.next_power_of_2(state_len)\n\n    def grid(META):\n        return (\n            batch,\n            triton.cdiv(dim, META[\"BLOCK_N\"]),\n        )\n\n    _causal_conv1d_update_kernel[grid](\n        # Pointers to matrices\n        x,\n        weight,\n        bias,\n        conv_state,\n        cache_seqlens,\n        conv_state_indices,\n        num_accepted_tokens,\n        out,\n        # Matrix dimensions\n        batch,\n        dim,\n        seqlen,\n        state_len,\n        num_cache_lines,\n        # stride\n        stride_x_seq,\n        stride_x_dim,\n        stride_x_token,\n        stride_w_dim,\n        stride_w_width,\n        stride_istate_seq,\n        stride_istate_dim,\n        stride_istate_token,\n        stride_state_indices,\n        stride_o_seq,\n        stride_o_dim,\n        stride_o_token,\n        # others\n        pad_slot_id,\n        # META\n        HAS_BIAS=bias is not None,\n        KERNEL_WIDTH=width,\n        SILU_ACTIVATION=activation in [\"silu\", \"swish\"],\n        IS_CONTINUOUS_BATCHING=conv_state_indices is not None,\n        IS_SPEC_DECODING=num_accepted_tokens is not None,\n        NP2_STATELEN=np2_statelen,\n        USE_PAD_SLOT=pad_slot_id is not None,\n        BLOCK_N=256,\n    )\n    if unsqueeze:\n        out = out.squeeze(-1)\n    return out"
    }
}
